import type { CSSProperties } from "react";

// Generated by strokit. Colors follow --sk-stroke; prefers-reduced-motion shows the final frame.
const css = `
.sk-wxsyyl-0 {
  stroke: var(--sk-stroke, #111111);
  stroke-dasharray: 0.2 0.8;
  animation: sk-wxsyyl-t0-comet calc(1600ms / var(--sk-speed, 1)) linear 0ms var(--sk-iterations, infinite) normal both;
  animation-play-state: var(--sk-play-state, running);
}
@keyframes sk-wxsyyl-t0-comet {
  0% {
    stroke-dashoffset: 1;
  }
  100% {
    stroke-dashoffset: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .sk-wxsyyl * {
    animation: none;
  }
  .sk-wxsyyl-0 {
    stroke-dasharray: none;
  }
}
`;

export type AnelCometProps = {
  /** Width and height (number = px). Defaults to the SVG's own size. */
  size?: number | string;
  /** Playback speed multiplier: 2 plays twice as fast. */
  speed?: number;
  /** true repeats forever, false plays once. Defaults to the exported animation. */
  loop?: boolean;
  paused?: boolean;
  className?: string;
  /** Accessible name. Defaults to "Anel". */
  label?: string;
};

export function AnelComet({
  size,
  speed = 1,
  loop,
  paused = false,
  className,
  label = "Anel",
}: AnelCometProps) {
  const style = {
    "--sk-speed": speed,
    "--sk-play-state": paused ? "paused" : "running",
    ...(loop === undefined ? {} : { "--sk-iterations": loop ? "infinite" : 1 }),
  } as CSSProperties;

  return (
    <svg
      viewBox="0 0 120 120"
      width={size ?? 120}
      height={size ?? 120}
      className={className ? `sk-wxsyyl ${className}` : "sk-wxsyyl"}
      style={style}
      role="img"
      aria-label={label}
    >
      <style>{css}</style>
      <title>{"Anel"}</title>
      <circle cx="60" cy="60" r="44" fill="none" stroke="#111111" strokeWidth="8" pathLength="1" className="sk-wxsyyl-0" />
      <circle cx="60" cy="60" r="26" fill="none" stroke="#111111" strokeWidth="4" pathLength="1" className="sk-wxsyyl-0" />
    </svg>
  );
}
